def clean(s):
 # Repeat a bounded number of passes because replacing a leading compound can expose a second one.
 for _ in range(3):
  for old,new in replacements.items():s=s.replace(old,new)
 return s
for r in out:
 r['reasoning']=clean('Verification: '+checks[int(r['id'].split('-')[-1])]) if '-problems-' in r['id'] else clean(r['reasoning']);r['assumptions']=[clean(x) for x in r['assumptions']]
 for key in ['scope','reviewNotice','referenceAnswer']:
  if key in r:r[key]=clean(r[key])
 for p in r['parts']:
  p['label']=clean(p['label']);p['explanation']=clean(p['explanation'])
  if p['type']=='choice':p['answer']=clean(p['answer']);p['options']=[clean(x) for x in p['options']]
# Exact ID and finite-result assertions.
root=Path(__file__).resolve().parents[2]
source=json.loads(gzip.decompress((root/'site/questions/physics.json.gz').read_bytes()))
expected={q['id'] for q in source if q['chapter']==20}
assert {r['id'] for r in out}==expected
assert len(out)==89
for r in out:
 for p in r['parts']:
  if p['type']=='numeric':assert math.isfinite(p['answer']) and p['tolerance']>=0 and (p['answer']==0 or p['tolerance']<abs(p['answer']))
  else:assert p['answer'] in p['options'] and len(set(p['options']))==3
out.sort(key=lambda r:(r['id'].split('-')[3],int(r['id'].split('-')[-1])))
Path(__file__).with_name('ch20.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print(len(out),'records',sum(len(r['parts']) for r in out),'fields')
